using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RiverRoadTests
{
    static WorldSession Start(bool blocked=true){var s=new WorldSession(RiverRoads.Create(blocked));Assert.Equal(ResultCode.Accepted,s.Submit(RiverRoads.Order(s.DiagnosticSnapshot(),"request:river"),s.Revision).Code);s.AdvanceTo(1);return s;}
    static long BridgeAt(WorldSession s)=>s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs.Single(l=>l.Edge=="nakajima-crossing").StartAt;
    [Fact] public void AddedCrossingIsAnExplicitNewDefinition(){var w=RiverRoads.Create();Assert.Equal(RiverRoads.Ruleset,w.Definitions.Ruleset);Assert.DoesNotContain(RiverRoads.Edges,e=>e.Id=="mikawa-concept");Assert.Contains("NOT a historical site",RiverRoads.Catalog.Caveat);Assert.Equal(RegionalCampaign.Ruleset,RegionalCampaign.Create().Definitions.Ruleset);}
    [Fact] public void UnknownBridgeClosureDoesNotChangeTheKnownPlanOrPosition(){var a=Start();var b=Start(false);var at=BridgeAt(a);a.AdvanceTo(at-1);b.AdvanceTo(at-1);Assert.Equal(ContractJson.Write(a.GetBranchView(ContractFixture.Officer)),ContractJson.Write(b.GetBranchView(ContractFixture.Officer)));Assert.Equal(ContractJson.Write(a.GetCourierView(ContractFixture.Lord)),ContractJson.Write(b.GetCourierView(ContractFixture.Lord)));}
    [Fact] public void ClosureIsSeenAtBankAndDetourActuallyCrossesTheAlternateEdge(){var s=Start();var at=BridgeAt(s);s.AdvanceTo(at);var w=s.DiagnosticSnapshot();Assert.Contains("nakajima-crossing",s.GetBranchView(ContractFixture.Officer).KnownBlockedEdges);Assert.Empty(s.GetBranchView(ContractFixture.Lord).KnownBlockedEdges);var legs=w.Branches!.Journeys.Single().Legs;Assert.Contains(legs,l=>l.Edge=="temporary-ford");Assert.DoesNotContain(legs,l=>l.Edge=="nakajima-crossing");Assert.Equal(RiverRoads.Nodes.Single(n=>n.Id=="bridge-west").Position,s.GetBranchView(ContractFixture.Officer).Position);s.AdvanceTo(100000);Assert.Equal(new EntityId("site:okazaki"),s.GetActorView(ContractFixture.Officer).Location.Site);}
    [Fact] public void OpenBridgeUsesItsOwnPhysicalSegment(){var s=Start(false);var at=BridgeAt(s);s.AdvanceTo(at+5);var leg=s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs.Single(l=>l.Edge=="nakajima-crossing");Assert.True(s.Seconds<leg.EndAt);Assert.DoesNotContain("temporary-ford",s.GetBranchView(ContractFixture.Officer).PlannedEdges);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]
    public void SaveRestoresApproachSeenAndMidCrossingWithoutPositionDrift(int stage){var s=Start();var at=BridgeAt(s);s.AdvanceTo(stage==0?at-1:at);if(stage==2){var leg=s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs.Single(l=>l.Edge=="temporary-ford");s.AdvanceTo((leg.StartAt+leg.EndAt)/2);}var root=Path.Combine(Path.GetTempPath(),"hakutai-river-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,RiverRoads.Create().Definitions);store.Save(s,"test",s.DiagnosticSnapshot().WorldId,new(.375,60));var host=new WorldSessionHost(new WorldSession(RiverRoads.Create()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("test"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.GetBranchView(ContractFixture.Officer)),ContractJson.Write(host.Current.GetBranchView(ContractFixture.Officer)));host.Current.SetPaused(false);s.AdvanceTo(100000);host.Current.AdvanceTo(100000);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Branches),ContractJson.Write(host.Current.DiagnosticSnapshot().Branches));Assert.Equal(s.DiagnosticSnapshot().Messaging.Attempts,host.Current.DiagnosticSnapshot().Messaging.Attempts);}
}
